const r = await Promise.allSettled([
  tools.exec_command({cmd:"rg -n \"getDatabaseConnTester|DatabasePinger|PingParams|connection_diagnostic|ConnectionDiagnostic\" lib api web | head -250",workdir:"/app",max_output_tokens:10000}),
  tools.exec_command({cmd:"rg -n \"SQLServer|sqlserver|ProtocolSQLServer|MSSQL|mssql\" lib/client/conntest lib/srv/db lib | head -300",workdir:"/app",max_output_tokens:12000}),
  tools.exec_command({cmd:"rg --files -g 'AGENTS.md' -g 'go.mod' -g '*conntest*' -g '*diagnostic*' lib | head -150",workdir:"/app",max_output_tokens:5000})
]); r.forEach((x,i)=>text(`${i}: ${JSON.stringify(x)}`));

const r = await Promise.allSettled([
  tools.exec_command({cmd:"grep -RInE 'getDatabaseConnTester|DatabasePinger|PingParams|connection_diagnostic|ConnectionDiagnostic' lib api web 2>/dev/null | head -250",workdir:"/app",max_output_tokens:10000}),
  tools.exec_command({cmd:"grep -RInE 'SQLServer|sqlserver|ProtocolSQLServer|MSSQL|mssql' lib/client/conntest lib/srv/db 2>/dev/null | head -300",workdir:"/app",max_output_tokens:12000}),
  tools.exec_command({cmd:"find . -name AGENTS.md -o -name go.mod -o -iname '*conntest*' -o -iname '*diagnostic*' | head -150",workdir:"/app",max_output_tokens:5000})
]); r.forEach((x,i)=>text(`${i}: ${JSON.stringify(x)}`));

