func TestMySQLErrors(t *testing.T) {
	p := MySQLPinger{}

	tests := []struct {
		name               string
		pingErr            error
		wantConnRefusedErr bool
		wantDBUserErr      bool
		wantDBNameErr      bool
	}{
		{
