func TestAccessSQLServer(t *testing.T) {
	ctx := context.Background()
	testCtx := setupTestContext(ctx, t, withSQLServer("sqlserver"))
	go testCtx.startHandlingConnections()

	tests := []struct {
		desc         string
		teleportUser string
		teleportRole string
		allowDbUsers []string
		dbUser       string
		err          string
	}{
		{
			desc:         "has access to all database users",
